from collections import OrderedDict


class EventProcessor:
    def __init__(self, apply, memory=1000):
        self.apply = apply
        self.memory = memory
        self.ids = OrderedDict()
        self.versions = {}

    def _remember(self, event_id):
        self.ids[event_id] = True
        while len(self.ids) > self.memory:
            self.ids.popitem(last=False)

    def handle(self, event):
        if event["id"] in self.ids:
            return "duplicate"
        applied = self.versions.get(event["object_id"])
        if applied is not None and event["version"] <= applied:
            self._remember(event["id"])
            return "stale"
        self.apply(event)
        self.versions[event["object_id"]] = event["version"]
        self._remember(event["id"])
        return "processed"

