def ev(id, obj, version):
    return {"id": id, "object_id": obj, "version": version}

class Store:
    def __init__(self):
        self.state = {}
        self.applied = []
    def __call__(self, event):
        self.applied.append(event["id"])
        self.state[event["object_id"]] = event["version"]

@test("duplicates are skipped")
def _():
    store = Store()
    p = EventProcessor(store)
    check_eq(p.handle(ev("e1", "o1", 1)), "processed")
    check_eq(p.handle(ev("e1", "o1", 1)), "duplicate")
    check_eq(store.applied, ["e1"])

@test("late events are stale")
def _():
    store = Store()
    p = EventProcessor(store)
    p.handle(ev("e1", "o1", 1))
    p.handle(ev("e3", "o1", 3))
    check_eq(p.handle(ev("e2", "o1", 2)), "stale")
    check_eq(p.handle(ev("e2", "o1", 2)), "duplicate")
    check_eq(p.handle(ev("e3b", "o1", 3)), "stale")
    check_eq(store.state, {"o1": 3})
    check_eq(p.handle(ev("x1", "o2", 1)), "processed")
    check_eq(store.applied, ["e1", "e3", "x1"])

@test("a failure can be retried")
def _():
    calls = []
    def flaky(event):
        calls.append(event["id"])
        if len(calls) == 1:
            raise RuntimeError("database is down")
    p = EventProcessor(flaky)
    check_raises(RuntimeError, p.handle, ev("e1", "o1", 1))
    check_eq(p.handle(ev("e1", "o1", 1)), "processed")
    check_eq(calls, ["e1", "e1"])

@test("memory is bounded")
def _():
    store = Store()
    p = EventProcessor(store, memory=3)
    for i in range(1, 6):
        p.handle(ev(f"e{i}", f"o{i}", 1))
    check_eq(p.handle(ev("e5", "o5", 1)), "duplicate")
    check_eq(p.handle(ev("e3", "o3", 1)), "duplicate")
    check_eq(p.handle(ev("e1", "o1", 1)), "stale")
    check_eq(p.handle(ev("e2", "o2", 2)), "processed")

